当前环境被 `clarification-hard-gate` hook 拦截，**所有 Write / StrReplace / Shell 均无法执行**，因此无法在本会话内直接改文件或跑 `verify-all.js`。下面给出可直接落地的完整改动说明；解除 hook 后按此 patch 应用即可。

---

## 阻塞说明

- `StrReplace`、`Write`、`Shell` 均返回：`clarification-hard-gate.ps1 returned invalid JSON`
- **Task is NOT fully verified**（未写入、未跑验证）

请在 Cursor 中临时禁用该 hook，或手动应用下列改动后执行：

```powershell
node prototype/scripts/verify-all.js
```

---

## 1. `user-portal-bridge.js`

**agentState 与常量：**

```javascript
var AGENT_PREPARE_MS = 1200;
var agentState = {
  item: null,
  draft: null,
  preparing: false
};
```

**点击路径（约 115 行）：** `openHistoryAgent(historyItem)` → `prepareHistoryAgent(historyItem)`

**在 `openHistoryAgent` 前插入：**

```javascript
function ensureHistoryAgentPreparingOverlay() {
  var el = document.getElementById('historyAgentPreparingOverlay');
  if (el) return el;
  el = document.createElement('div');
  el.id = 'historyAgentPreparingOverlay';
  el.className = 'modal-overlay aioq-agent-preparing-overlay hidden';
  el.setAttribute('role', 'status');
  el.setAttribute('aria-live', 'polite');
  el.innerHTML = '<div class="modal-overlay-content">' +
    '<div class="spinner" aria-hidden="true"></div>' +
    '<p class="title">正在分析对话，生成智能体草稿…</p>' +
    '<p class="sub">请稍候</p>' +
  '</div>';
  document.body.appendChild(el);
  return el;
}

function showHistoryAgentPreparing() {
  ensureHistoryAgentPreparingOverlay().classList.remove('hidden');
}

function hideHistoryAgentPreparing() {
  var overlay = document.getElementById('historyAgentPreparingOverlay');
  if (overlay) overlay.classList.add('hidden');
}

function prepareHistoryAgent(item) {
  if (!item || agentState.preparing) return;
  if (!document.getElementById('historyAgentModal')) {
    toast('请到对话工作台使用此功能');
    return;
  }
  agentState.preparing = true;
  showHistoryAgentPreparing();
  setTimeout(function () {
    try {
      openHistoryAgent(item);
    } finally {
      agentState.preparing = false;
      hideHistoryAgentPreparing();
    }
  }, AGENT_PREPARE_MS);
}
```

**CSS 追加（`style.css`）：**

```css
.aioq-agent-preparing-overlay {
  z-index: 1200;
  background: rgba(15, 23, 42, 0.45);
}
```

---

## 2. 文件 chip 上移（`index.html` + `user-chat-portal.js` + `style.css`）

**index.html** — 在 `#sessionActiveSkills` 下方增加：

```html
<div class="skill-chip-list aioq-active-files hidden" id="sessionActiveFiles" aria-label="已上传文件"></div>
```

**user-chat-portal.js** — 拆分渲染：

```javascript
function renderFileChips() {
  if (!els.sessionActiveFiles) return;
  var chips = composerContext.attachments.map(function (file) {
    return '<span class="skill-chip aioq-file-chip">' + escapeHtml(file.name) +
      '<button type="button" data-remove-attachment="' + escapeHtml(file.id) + '" aria-label="移除附件">×</button></span>';
  });
  els.sessionActiveFiles.classList.toggle('hidden', chips.length === 0);
  els.sessionActiveFiles.innerHTML = chips.join('');
}

function renderNoteChips() {
  if (!els.attachChip) return;
  var chips = [];
  selectedNotes().forEach(function (note) {
    chips.push(
      '<span class="aioq-context-token aioq-context-token--note" data-note-ref="' + escapeHtml(note.id) + '" tabindex="0" role="button" title="查看笔记摘要">' +
        escapeHtml(note.title) +
        '<button type="button" data-remove-note="' + escapeHtml(note.id) + '" aria-label="移除笔记">×</button>' +
      '</span>'
    );
  });
  els.attachChip.classList.toggle('hidden', chips.length === 0);
  els.attachChip.innerHTML = chips.join('');
}

function renderAttachChip() {
  renderFileChips();
  renderNoteChips();
}
```

- `els` 增加：`sessionActiveFiles: document.getElementById('sessionActiveFiles')`
- 新增 `#sessionActiveFiles` 的 click 监听，处理 `data-remove-attachment`
- `#attachChip` 监听去掉 attachment 分支，只保留笔记

**style.css：**

```css
.aioq-active-files {
  margin-bottom: 8px;
  flex-wrap: nowrap;
  overflow-x: auto;
  overflow-y: hidden;
}
.aioq-file-chip {
  flex-shrink: 0;
  max-width: 180px;
}
```

