#!/usr/bin/env node
/**
 * Cursor preToolUse hook for Write|Edit — Node implementation (no PS stdin deadlock).
 * Reads gate-state.json; blocks only when gateStatus=pending for cwd.
 */
'use strict';

const fs = require('fs');
const path = require('path');

const GATE_ROOT = path.join(process.env.USERPROFILE || process.env.HOME || '', '.ai-workspace', 'clarifications');
const GATE_STATE = path.join(GATE_ROOT, 'gate-state.json');
const KEYWORDS_PATH = path.join(process.env.USERPROFILE || '', '.ai-workspace', 'scripts', 'clarification-gate-keywords.json');

const BLOCK_TOOLS = new Set(['Write', 'Edit', 'MultiEdit', 'StrReplace', 'apply_patch']);
const DEFAULT_ALLOWED = [
  '\\.ai-workspace\\clarifications\\',
  '\\clarifications\\',
  '\\docs\\intent\\',
  '\\docs\\ideas\\',
  '\\.github\\agent\\memory\\',
  '\\decisions-log.md',
  '\\task-history.md',
  '\\project-memory.md'
];

function readStdin(timeoutMs) {
  return new Promise(function (resolve) {
    let data = '';
    let done = false;
    const finish = function (value) {
      if (done) return;
      done = true;
      resolve(value || null);
    };
    const timer = setTimeout(function () {
      try { process.stdin.destroy(); } catch (e) { /* ignore */ }
      finish(data || null);
    }, timeoutMs);
    process.stdin.setEncoding('utf8');
    process.stdin.on('data', function (chunk) { data += chunk; });
    process.stdin.on('end', function () {
      clearTimeout(timer);
      finish(data || null);
    });
    process.stdin.on('error', function () {
      clearTimeout(timer);
      finish(null);
    });
    process.stdin.resume();
  });
}

function loadAllowedFragments() {
  try {
    const raw = fs.readFileSync(KEYWORDS_PATH, 'utf8');
    const cfg = JSON.parse(raw);
    if (cfg && Array.isArray(cfg.allowedPathFragments)) return cfg.allowedPathFragments;
  } catch (e) { /* ignore */ }
  return DEFAULT_ALLOWED;
}

function normalizeCwd(cwd) {
  if (!cwd) return process.cwd().toLowerCase();
  try { return path.resolve(cwd).toLowerCase(); }
  catch (e) { return String(cwd).toLowerCase(); }
}

function loadGateEntry(cwdNorm) {
  try {
    const raw = fs.readFileSync(GATE_STATE, 'utf8');
    const store = JSON.parse(raw);
    if (!store || !store.entries) return null;
    return store.entries[cwdNorm] || null;
  } catch (e) {
    return null;
  }
}

function getToolContext(data) {
  if (!data || typeof data !== 'object') return null;
  const toolName = data.tool_name || data.toolName || null;
  const toolInput = data.tool_input || data.toolInput || null;
  let cwd = data.cwd || null;
  if (!cwd && Array.isArray(data.workspace_roots) && data.workspace_roots[0]) {
    cwd = data.workspace_roots[0];
  }
  return { toolName, toolInput, cwd };
}

function getWriteTarget(toolInput) {
  if (!toolInput || typeof toolInput !== 'object') return null;
  return toolInput.file_path || toolInput.path || null;
}

function isAllowedPath(target, fragments) {
  if (!target) return false;
  const norm = String(target).replace(/\//g, '\\').toLowerCase();
  return fragments.some(function (frag) {
    return norm.includes(String(frag).toLowerCase());
  });
}

function shouldBlock(ctx) {
  if (process.env.CLARIFICATION_GATE_OFF === '1') return false;
  if (!ctx || !ctx.toolName || !BLOCK_TOOLS.has(ctx.toolName)) return false;
  const entry = loadGateEntry(normalizeCwd(ctx.cwd));
  if (!entry) return false;
  const status = entry.gateStatus || 'exempt';
  if (status !== 'pending') return false;
  const target = getWriteTarget(ctx.toolInput);
  if (!target) return true;
  return !isAllowedPath(target, loadAllowedFragments());
}

function emitAllow() {
  process.stdout.write(JSON.stringify({ permission: 'allow' }));
}

function emitDeny(draftPath) {
  const reason = 'Type B fuzzy task - confirm before Write/Edit.';
  const draft = draftPath || '(~/.ai-workspace/clarifications/)';
  process.stdout.write(JSON.stringify({
    permission: 'deny',
    user_message: 'Clarification gate: complete Mini-Spec before code edits. Draft: ' + draft,
    agent_message: 'CLARIFICATION GATE: ' + reason + ' Draft: ' + draft
  }));
}

readStdin(2000).then(function (raw) {
  try {
    let data = null;
    if (raw && raw.trim()) {
      try { data = JSON.parse(raw); } catch (e) { data = null; }
    }
    const ctx = getToolContext(data);
    if (!shouldBlock(ctx)) {
      emitAllow();
      return;
    }
    const entry = loadGateEntry(normalizeCwd(ctx.cwd));
    emitDeny(entry && entry.draftPath);
  } catch (e) {
    emitAllow();
  }
});

